def transform(g):
    h,w=len(g),len(g[0])
    color=next(v for r in g for v in r if v)
    # connected components (8-conn) of color cells; apex = topmost cell
    import collections
    seen=set(); comps=[]
    cells=[(r,c) for r in range(h) for c in range(w) if g[r][c]==color]
    cs=set(cells)
    for s in cells:
        if s in seen: continue
        comp=[]; st=[s]; seen.add(s)
        while st:
            r,c=st.pop(); comp.append((r,c))
            for dr in(-1,0,1):
                for dc in(-1,0,1):
                    n=(r+dr,c+dc)
                    if n in cs and n not in seen: seen.add(n); st.append(n)
        comps.append(comp)
    out=[row[:] for row in g]
    for comp in comps:
        apex=min(comp)  # topmost
        r0,c0=apex
        for r in range(h):
            k=r-r0
            if k<=0: continue
            for c in range(w):
                if abs(c-c0)<k and g[r][c]==0:
                    out[r][c]=2
    return out

