def transform(g):
    h,w=len(g),len(g[0])
    color=next(v for r in g for v in r if v)
    out=[row[:] for row in g]
    for r in range(h):
        cols=[c for c in range(w) if g[r][c]==color]
        for i in range(len(cols)-1):
            for c in range(cols[i]+1, cols[i+1]):
                if g[r][c]==0: out[r][c]=2
    return out
